      link.href = 'assets/functions/aiCopilot/aiCopilotStyles.css';
      document.head.appendChild(link);
    }

    // Inyectar Widget HTML
    const wrapper = document.createElement('div');
    wrapper.id = 'v1r3-ai-wrapper';
    wrapper.innerHTML = `
      <button id="v1r3-ai-trigger" aria-label="Abrir Asistente AI de Victor Reguillo">
        <span class="ai-pulse"></span>
        <span>V1R3-COPILOT [AI]</span>
      </button>

      <div id="v1r3-ai-modal" role="dialog" aria-modal="true" aria-label="Asistente Virtual">
        <div class="ai-modal-header">
          <div class="ai-header-title">
            <span style="color: var(--ai-border)">●</span> <span>V1R3_SEC_ASSISTANT v2.4</span>
          </div>
          <button class="ai-close-btn" id="ai-close-trigger">&times;</button>
        </div>
        <div class="ai-chat-body" id="ai-chat-body">
          <div class="ai-msg bot">
            ¡Hola! Soy el copiloto virtual de Victor Reguillo. ¿En qué puedo ayudarte a evaluar su perfil técnico o proyectos hoy?
          </div>
        </div>
        <div class="ai-chips-container">
          <button class="ai-chip" data-query="stack">¿Cuál es su stack?</button>
          <button class="ai-chip" data-query="disponible">¿Está disponible?</button>
          <button class="ai-chip" data-query="cv">Descargar CV</button>
          <button class="ai-chip" data-query="contacto">Contacto</button>
        </div>
        <div class="ai-modal-footer">
          <input type="text" class="ai-input" id="ai-user-input" placeholder="Escribe tu consulta..." />
          <button class="ai-send-btn" id="ai-send-trigger">SEND</button>
        </div>
      </div>
    `;
    document.body.appendChild(wrapper);
  }

  bindEvents() {
    const trigger = document.getElementById('v1r3-ai-trigger');
    const modal = document.getElementById('v1r3-ai-modal');
    const closeBtn = document.getElementById('ai-close-trigger');
    const sendBtn = document.getElementById('ai-send-trigger');
    const input = document.getElementById('ai-user-input');
    const chips = document.querySelectorAll('.ai-chip');

    trigger.addEventListener('click', () => {
      this.isOpen = !this.isOpen;
      modal.classList.toggle('active', this.isOpen);
      if (this.isOpen) input.focus();
    });

    closeBtn.addEventListener('click', () => {
      this.isOpen = false;
      modal.classList.remove('active');
    });

    const handleUserMessage = (text) => {
      if (!text.trim()) return;
      this.appendMessage(text, 'user');
      input.value = '';

      // Simular tiempo de procesamiento neuronal (typing indicator)
      setTimeout(() => {
        const response = queryAI(text);
        this.appendMessage(response, 'bot');
      }, 400);
    };

    sendBtn.addEventListener('click', () => handleUserMessage(input.value));
    input.addEventListener('keypress', (e) => {
      if (e.key === 'Enter') handleUserMessage(input.value);
    });

    chips.forEach(chip => {
      chip.addEventListener('click', () => {
        const queryText = chip.getAttribute('data-query');
        handleUserMessage(queryText);
      });
    });
  }

  appendMessage(text, sender) {
    const chatBody = document.getElementById('ai-chat-body');
    const msgDiv = document.createElement('div');
    msgDiv.className = `ai-msg ${sender}`;
    msgDiv.innerHTML = text;
    chatBody.appendChild(msgDiv);
    chatBody.scrollTop = chatBody.scrollHeight;
  }
}
